import csv
import os

DATASET_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "dataset")


def _parse_decimal(s):
    s = s.strip()
    if "," in s and "." not in s:
        s = s.replace(",", ".")
    return float(s)


def answer() -> int:
    catalog_path = os.path.join(DATASET_DIR, "product_catalog.csv")
    dispatches_path = os.path.join(DATASET_DIR, "warehouse_dispatches.csv")

    catalog = {}
    ean_map = {}
    with open(catalog_path) as f:
        for row in csv.DictReader(f):
            info = {
                "price": _parse_decimal(row["unit_price"]),
                "category": row["storage_category"],
                "weight": float(row["unit_weight_kg"]),
            }
            catalog[row["product_id"]] = info
            ean_map[row["ean_code"]] = info

    # The only temperature-log excursion in July 2023 occurs on 2023-07-18
    # 00:00-06:00, when both the Meat and Frozen zones spike far above their
    # safe thresholds (Meat up to ~16.3C vs 4C max; Frozen up to ~-2.6C vs
    # -10C max), while Dairy and Dry stay within range all month.
    # This coincides exactly with an anomalous dispatch batch at
    # 2023-07-18 03:17:00 (dispatch_ids 127-134): the only dispatches ever
    # recorded at 3am, all Meat/Frozen products, including a 220-unit
    # Vanilla Ice Cream dispatch versus a normal batch size of ~12-25.
    # This batch is the disposal/spoilage write-off and must be excluded
    # from revenue.
    disposal_ids = {str(i) for i in range(127, 135)}

    total_revenue = 0.0
    with open(dispatches_path) as f:
        for row in csv.DictReader(f):
            if row["dispatch_id"] in disposal_ids:
                continue
            info = catalog.get(row["product_id"]) or ean_map.get(row["product_id"])
            total_revenue += int(row["quantity"]) * info["price"]

    return round(total_revenue)


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

